export const VERSION='1.0.0';
export const STORAGE_KEY='qf-studio-chapter-02-v1';
export const STEPS=[['start','Your maths workspace',10],['returns','Measure a return',25],['compound','Compound over time',25],['discount','Bring money to today',30],['inflation','Measure buying power',25],['lab','Explore the growth lab',35],['assessment','Your independent check',20],['finish','Save your calculation card',10]];
export const freshState=()=>({version:VERSION,fields:{},done:{},checked:{},practiceAttempts:[],runs:[],attempts:[],card:null,lastPage:'start'});
export function restoreState(raw){try{const s=JSON.parse(raw),record=v=>v&&typeof v==='object'&&!Array.isArray(v);if(s?.version!==VERSION||!record(s.fields)||!Object.entries(s.fields).every(([k,v])=>['setup','handVerified','quizDirty','cardCriteria',...Object.keys(PRACTICE).map(step=>step+'Criteria')].includes(k)?typeof v==='boolean':k==='quizSet'?['0','1'].includes(v):typeof v==='string')||!record(s.done)||!Object.values(s.done).every(v=>typeof v==='boolean')||!record(s.checked)||!Object.values(s.checked).every(v=>typeof v==='boolean')||!['practiceAttempts','runs','attempts'].every(k=>Array.isArray(s[k])))return freshState();if(!s.practiceAttempts.every(a=>record(a)&&typeof a.id==='string'&&typeof a.raw==='string'&&typeof a.correct==='boolean'))return freshState();const runs=s.runs.map(r=>{if(!record(r)||typeof r.prediction!=='string'||typeof r.time!=='string')throw new Error('Invalid run');return {...growthScenario(r),prediction:r.prediction,time:r.time};});const attempts=s.attempts.map(a=>{if(!record(a)||![0,1].includes(a.set)||!record(a.answers)||!Object.values(a.answers).every(v=>typeof v==='string')||typeof a.time!=='string'||(a.revision!==undefined&&typeof a.revision!=='string'))throw new Error('Invalid attempt');return {...a,...grade(ASSESSMENTS[a.set],a.answers)};});if(s.card!==null&&(!record(s.card)||!['method','check','limits'].every(k=>typeof s.card[k]==='string')))return freshState();return {...freshState(),...s,runs,attempts};}catch{return freshState();}}
export function number(raw,label='Value'){if(raw===null||raw===undefined||typeof raw==='boolean'||String(raw).trim()==='')throw new Error(`${label} is required. Use a number without £ or %.`);const n=Number(raw);if(!Number.isFinite(n))throw new Error(`${label} must be a finite number.`);return n;}
export function totalReturn(start,end,distribution=0){start=number(start);end=number(end);distribution=number(distribution);if(start<=0||end<0||distribution<0)throw new Error('Use a positive starting price and nonnegative ending price and distribution.');return (end-start+distribution)/start*100;}
export function compoundReturn(returns){if(!Array.isArray(returns)||!returns.length)throw new Error('Supply at least one return.');return (returns.reduce((v,r)=>{r=number(r);if(r < -100)throw new Error('An unleveraged period return cannot be below −100%.');return v*(1+r/100);},1)-1)*100;}
export function annualGrowth(start,end,years){start=number(start);end=number(end);years=number(years);if(start<=0||end<0||years<=0)throw new Error('Starting value and years must be positive; ending value cannot be negative.');return ((end/start)**(1/years)-1)*100;}
export function presentValue(flows,rate){rate=number(rate);if(rate<=-100||!Array.isArray(flows)||!flows.length)throw new Error('Supply cash flows and a discount rate above −100%.');return flows.reduce((sum,f)=>{const amount=number(f.amount),year=number(f.year);if(year<0)throw new Error('Cash-flow time cannot be negative.');return sum+amount/(1+rate/100)**year;},0);}
export function realReturn(nominal,inflation){nominal=number(nominal);inflation=number(inflation);if(nominal < -100||inflation<=-100)throw new Error('Use a nominal return at least −100% and inflation above −100%.');return ((1+nominal/100)/(1+inflation/100)-1)*100;}
export function growthScenario(input){const principal=number(input.principal,'Starting amount'),rate=number(input.rate,'Annual growth rate'),inflation=number(input.inflation,'Inflation'),years=number(input.years,'Years'),goal=number(input.goal,'Future payment');if(principal<1||principal>1e6||rate<0||rate>25||inflation<0||inflation>20||!Number.isInteger(years)||years<1||years>40||goal<1||goal>1e7)throw new Error('Use £1–£1,000,000 to start, growth 0–25%, inflation 0–20%, 1–40 whole years, and a future payment of £1–£10,000,000.');const rows=Array.from({length:years+1},(_,year)=>({year,nominal:principal*(1+rate/100)**year,simple:principal*(1+rate/100*year),real:principal*((1+rate/100)/(1+inflation/100))**year}));return {principal,rate,inflation,years,goal,nominal:rows.at(-1).nominal,simple:rows.at(-1).simple,real:rows.at(-1).real,realRate:realReturn(rate,inflation),goalPV:presentValue([{amount:goal,year:years}],rate),rows};}
const numeric=(id,objective,title,answer,tolerance,hint,why)=>({id,objective,title,answer,tolerance,hint,why,type:'number'});
const choice=(id,objective,title,options,answer,why,critical=false)=>({id,objective,title,options,answer,why,type:'choice',critical});
export const PRACTICE={
 returns:[numeric('r1','CH2-01','Buy at £100, end at £104, receive a £3 distribution. Total return (%)?',7,.01,'Include both the price change and the distribution, then divide by the £100 starting value.','(104 − 100 + 3) ÷ 100 × 100 = 7%. The price-only return is 4%.'),numeric('r2','CH2-01','New case: buy at £80, end at £76, receive £2. Total return (%)?',-2.5,.01,'The £2 receipt partly offsets a £4 capital loss. Keep the negative sign.','(76 − 80 + 2) ÷ 80 × 100 = −2.5%. A distribution does not guarantee a positive total return.')],
 compound:[numeric('c1','CH2-02','£500 earns 8% at each year end, reinvested, for two years. Ending value (£)?',583.2,.011,'Multiply £500 by 1.08 twice. Do not add 16% to the starting value.','500 × 1.08² = £583.20. The simple-interest comparison would be £580.'),numeric('c2','CH2-02','A return of +20% followed by −20%: cumulative return (%)?',-4,.01,'Start with £100. Multiply by 1.20, then by 0.80.','100 × 1.20 × 0.80 = 96, so the cumulative return is −4%, despite the arithmetic average being 0%.'),numeric('c3','CH2-02','£100 grows to £121 over exactly two years, with no external cash flows. CAGR (%)?',10,.01,'Find the equal annual multiplier: (121 ÷ 100) raised to the power 1/2.','(121 ÷ 100)^(1/2) − 1 = 0.10 = 10% per year. CAGR summarises a path; it does not describe its volatility.')],
 discount:[numeric('p1','CH2-03','Receive £926.10 at the end of year 3. At a 5% annual effective discount rate, present value (£)?',800,.011,'Divide by 1.05 three times, rather than subtracting 15%.','926.10 ÷ 1.05³ = £800. All values are on the time-0 basis.'),numeric('p2','CH2-03','A bond pays £20 at year 1 and £1,020 at year 2 (including principal). At 5%, total present value (£)?',presentValue([{amount:20,year:1},{amount:1020,year:2}],5),.011,'Discount the year-1 and year-2 payments separately, then add them.','20 ÷ 1.05 + 1,020 ÷ 1.05² = £944.22. The last payment already includes the principal; do not add £1,000 again.')],
 inflation:[numeric('i1','CH2-04','Nominal return 6%, inflation 4%, over the same year. Exact real return (%)? Round to 2 decimals.',realReturn(6,4),.011,'Use (1.06 ÷ 1.04 − 1) × 100. Subtraction is only an approximation.','The exact real return is 1.9231%, or 1.92%. The 2% subtraction approximation differs.'),numeric('i2','CH2-04','£1,000 grows by 3% while prices rise 5%. Ending purchasing power in starting-year pounds (£)?',1000*1.03/1.05,.011,'Divide the £1,030 nominal ending value by the price-level multiplier 1.05.','£1,030 ÷ 1.05 = £980.95 in starting-year pounds. Nominal growth can coexist with a loss of purchasing power.')]
};
function assessment(set){const B=set===1;return [
 numeric('a1','CH2-01',B?'Buy at £1,000, end at £1,020 and receive £30. Total return (%)?':'Buy at £200, end at £210 and receive £6. Total return (%)?',B?5:8,.01,'Include the cash receipt. Divide the net gain by the starting price.',B?'(1,020 − 1,000 + 30) ÷ 1,000 × 100 = 5%.':'(210 − 200 + 6) ÷ 200 × 100 = 8%.'),
 numeric('a2','CH2-02',B?'£800 compounds at 4% annually for three years. Ending value (£)?':'£5,000 compounds at 6% annually for two years. Ending value (£)?',B?800*1.04**3:5000*1.06**2,.011,'Multiply the starting amount by the annual growth factor once per year.',B?'800 × 1.04³ = £899.89.':'5,000 × 1.06² = £5,618.00.'),
 {...numeric('a3','CH2-02',B?'A +10% year followed by a −10% year: cumulative return (%)?':'A +25% year followed by a −20% year: cumulative return (%)?',B?-1:0,.01,'Multiply the period growth factors. Addition is not compounding.',B?'1.10 × 0.90 − 1 = −1%.':'1.25 × 0.80 − 1 = 0%.'),critical:true},
 numeric('a4','CH2-02',B?'£2,000 becomes £2,420 in exactly two years, no external flows. CAGR (%)?':'£1,000 becomes £1,331 in exactly three years, no external flows. CAGR (%)?',10,.01,'Take the ending-to-starting ratio to the power 1/years, then subtract one.',B?'(2,420 ÷ 2,000)^(1/2) − 1 = 10%.':'(1,331 ÷ 1,000)^(1/3) − 1 = 10%.'),
 numeric('a5','CH2-03',B?'£1,500 due at year 3, discounted at 4% annually. Present value (£)?':'£1,200 due at year 2, discounted at 5% annually. Present value (£)?',B?1500/1.04**3:1200/1.05**2,.011,'Divide the future payment by (1 + rate) raised to its payment year.',B?'1,500 ÷ 1.04³ = £1,333.49.':'1,200 ÷ 1.05² = £1,088.44.'),
 numeric('a6','CH2-03',B?'Bond: £30 at year 1 and £1,030 at year 2. Discount at 4%. Present value (£)?':'Bond: £40 at year 1 and £1,040 at year 2. Discount at 5%. Present value (£)?',B?presentValue([{amount:30,year:1},{amount:1030,year:2}],4):presentValue([{amount:40,year:1},{amount:1040,year:2}],5),.011,'Discount each dated payment separately; the final payment includes principal.',B?'30 ÷ 1.04 + 1,030 ÷ 1.04² = £981.14.':'40 ÷ 1.05 + 1,040 ÷ 1.05² = £981.41.'),
 {...numeric('a7','CH2-04',B?'Nominal return 3%, inflation 6%, over one year. Exact real return (%) to 2 decimals?':'Nominal return 4%, inflation 7%, over one year. Exact real return (%) to 2 decimals?',B?realReturn(3,6):realReturn(4,7),.011,'Divide one plus nominal return by one plus inflation, then subtract one.',B?'1.03 ÷ 1.06 − 1 = −2.83% rounded.':'1.04 ÷ 1.07 − 1 = −2.80% rounded.'),critical:true},
 choice('a8','CH2-05',B?'A toy model uses a constant 4% rate for 20 years. Which conclusion is justified?':'Your lab grows a balance at a constant 5% for 10 years. Which statement is justified?',['The chosen rate guarantees future investment results','The result is conditional on the stated rate, timing, reinvestment and cost assumptions','A positive ending balance proves that risk has disappeared'],1,'An assumed rate is an input, not a forecast. These calculations omit default, volatility and other real-market features.',true)
];}
export const ASSESSMENTS=[assessment(0),assessment(1)];
export function checkAnswer(q,raw){if(q.type==='choice')return raw!==''&&raw!==null&&raw!==undefined&&Number(raw)===q.answer;try{return Math.abs(number(raw)-q.answer)<=q.tolerance+1e-10;}catch{return false;}}
export function grade(questions,answers){const details=questions.map(q=>({id:q.id,correct:checkAnswer(q,answers[q.id]),critical:!!q.critical}));const score=details.filter(d=>d.correct).length;return {score,total:questions.length,details,passed:score>=7&&details.filter(d=>d.critical).every(d=>d.correct)};}
export function invalidate(state,id){let area=null;if(id==='setup'&&!state.fields.setup){delete state.done.start;area='start';}for(const [step,qs]of Object.entries(PRACTICE))if(qs.some(q=>q.id===id)){delete state.checked[id];delete state.done[step];area=step;}for(const step of Object.keys(PRACTICE))if(id===`${step}Reflection`||id===`${step}Criteria`){delete state.done[step];area=step;}if(id==='hand'){state.fields.handVerified=false;delete state.done.lab;area='lab';}if(id==='labReflection'){delete state.done.lab;area='lab';}if(id.startsWith('quiz-')){state.fields.quizDirty=true;delete state.done.assessment;area='assessment';}if(id==='quizRevision'){delete state.done.assessment;area='assessment';}if(id.startsWith('card')){state.card=null;delete state.done.finish;area='finish';}return area;}
export function pairedInflationRuns(runs){return runs.some(a=>runs.some(b=>a.inflation!==b.inflation&&['principal','rate','years','goal'].every(k=>a[k]===b[k])));}
